/**
 * Jinx Heretic + Pit-Hag: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Heretic
 * Wiki: https://wiki.bloodontheclocktower.com/Pit-Hag
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { dispatch } from '#lib/core/engine/index.ts';
import {
	jinxForbidsBecoming,
	jinxRulesBetween,
	jinxSetupWarnings,
	scriptJinxes
} from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';

describe('Heretic + Pit-Hag jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'heretic', 'pithag');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('heretic')?.name).toBe('Heretic');
		expect(data.byId.get('pithag')?.name).toBe('Pit-Hag');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['heretic', 'pithag'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['heretic'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['pithag'])).not.toContain(jinx);
	});

	// The Heretic's Related Jinxes: only one of the Heretic and the Pit-Hag may be in play.
	it('is data in the Heretic rules: only one of the two may be in play', () => {
		expect(jinxRulesBetween('heretic', 'pithag', committedCharacters())).toEqual({
			exclusive: true
		});
		expect(jinxRulesBetween('pithag', 'heretic', committedCharacters())).toEqual({
			exclusive: true
		});
	});

	it('warns at setup when both are chosen, and not when one is', () => {
		const jinxes = scriptJinxes(
			data.jinxes,
			['heretic', 'pithag', 'chef'],
			undefined,
			committedCharacters()
		);
		expect(jinxes.map((j) => j.exclusive)).toEqual([true]);
		expect(jinxSetupWarnings(jinxes, ['heretic', 'pithag'])).toHaveLength(1);
		expect(jinxSetupWarnings(jinxes, ['heretic', 'chef'])).toEqual([]);
	});

	// The Djinn's page: the Pit-Hag cannot create a Heretic. A change made anyway warns.
	it('warns when a player becomes one while the other is in play, either way round', () => {
		const s = scenario(['pithag', 'chef', 'empath', 'imp']);
		const codes = (seat: string, characterId: string) => {
			const result = dispatch(
				s.session,
				{ type: 'AssignCharacter', seatId: s.seat(seat), characterId },
				s.ctx
			);
			return result.ok ? result.warnings.map((w) => w.code) : [];
		};
		expect(jinxForbidsBecoming(s.game, s.seat('chef'), 'heretic', s.characters)).toBe('pithag');
		expect(codes('chef', 'heretic')).toContain('jinxed-character');
		// The Pit-Hag's own seat becoming the Heretic leaves no Pit-Hag in play.
		expect(jinxForbidsBecoming(s.game, s.seat('pithag'), 'heretic', s.characters)).toBeUndefined();
		const heretic = scenario(['heretic', 'chef', 'empath', 'imp']);
		expect(
			jinxForbidsBecoming(heretic.game, heretic.seat('chef'), 'pithag', heretic.characters)
		).toBe('heretic');
		expect(jinxForbidsBecoming(s.game, s.seat('chef'), 'saint', s.characters)).toBeUndefined();
	});
});
